  {% endif %};
'
SET
  @TechnicalDescription_a3ac463e54b5 = N'Nunjucks-parameterized on CompanyIDs (optional array of Company UUIDs from the dashboard''s company chips, passed through the sqlIn filter; omitted entirely when empty, since sqlIn renders (NULL) for an empty array and would match nothing). Aggregates __mj_BizAppsContracts.vwContracts where HasModifications = 1 and State IN (''Active'',''Executed''). Always returns exactly one row, with zeros when nothing matches. The CompanyIDs parameter row is created by the server''s query-extraction pipeline rather than declared in metadata/, and reaches a host inside the release Metadata_Sync capture; see the header of SQL/contracts-special-terms.sql for why it cannot be declared.'
